#!/bin/sh
# Copyright 2026 Simon Ostendorf
# SPDX-License-Identifier: Apache-2.0
#
# Regenerates internal/config/gitkeys.go from the key list the installed
# git prints. The generated list is what tells a key git documents apart
# from one it does not, so a profile key gitcd has never heard of is
# refused rather than written into a generated file unexamined.
#
# Run it after a git upgrade, through "task generate:gitkeys", and commit
# the result. The git version it ran against is recorded in the file.
#
# A key is reduced to its section and its final name, lowercased, since
# that is the pair internal/config matches on: a subsection is a name the
# user invents, so "diff.<driver>.command" and "diff.command" are one
# entry. A "<name>" segment is therefore removed rather than used to
# discard the key, or every subsection keyed setting, "mergetool.<tool>.
# layout" among them, would be missing from the list and refused.
#
# Entries whose own final name is a wildcard, "alias.*" or "feature.*",
# are left out: they describe a section whose key names git does not
# enumerate, so they say nothing about any individual key.

set -eu

out=internal/config/gitkeys.go
version=$(git version)

keys=$(
	git help -c |
		grep '^[a-zA-Z][a-zA-Z0-9]*\.' |
		sed 's/\.<[^>]*>//g' |
		grep -v '[*<>:]' |
		awk -F. 'NF >= 2 { printf "%s.%s\n", tolower($1), tolower($NF) }' |
		sort -u
)

count=$(printf '%s\n' "$keys" | wc -l | tr -d ' ')

{
	printf '// Copyright 2026 Simon Ostendorf\n'
	printf '// SPDX-License-Identifier: Apache-2.0\n\n'
	printf '// Code generated by scripts/generate-git-config-keys.sh. DO NOT EDIT.\n'
	printf '// Source: %s\n\n' "$version"
	printf 'package config\n\n'
	printf '// knownGitKeyPairs is every git config key the git named above\n'
	printf '// documents, reduced to "section.name" with the subsection left\n'
	printf '// out and both parts lowercased, one per line. %s entries.\n' "$count"
	printf 'const knownGitKeyPairs = `\n'
	printf '%s\n' "$keys"
	printf '`\n'
} >"$out"

gofmt -w "$out"
printf 'wrote %s: %s entries from %s\n' "$out" "$count" "$version"
